// ValidateDismissRequestBody runs the validations defined on DismissRequestBody
func ValidateDismissRequestBody(body *DismissRequestBody) (err error) {
	if body.RegistryEntryID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("registry_entry_id", "body"))
	}
	if body.RegistryEntryID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.registry_entry_id", *body.RegistryEntryID, goa.FormatUUID))
	}
	return
}

